-- IPBus wrapper for the prototype local-bus register file.
--   IPBus -> local bus (t_lb_m2s / t_lb_s2m) -> regfile
--
-- Generated by bust. IPBus is itself a single-beat, hold-until-ack protocol, so
-- the bridge is pure combinational glue: a strobe drives one local-bus
-- transaction (wen for write, ren for read) and the regfile's response
-- (ack/err/rdata) is forwarded straight back. No FSM and no register stage of its
-- own: the regfile's single registered cycle is the whole latency, and its
-- response guard provides transaction separation. The 32-bit IPBus address is
-- sliced to the local-bus width. The regfile selects the register and checks
-- G_BASE_ADDRESS within that width, so any bits above it are decoded upstream.
-- IPBus's sync active-high reset passes straight to the regfile.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

library ipbus;
use ipbus.ipbus.all;

use work.prototype_localbus_pkg.all;
use work.prototype_regfile_pkg.all;

entity prototype_ipb_endpoint is
  generic (
    G_BASE_ADDRESS       : unsigned(31 downto 0) := 32x"0";
    G_CHECK_BASE_ADDRESS : boolean := true;
    G_MODULE_ADDR_WIDTH  : natural := C_MODULE_ADDR_WIDTH
  );
  port (
    clk     : in  std_logic;
    reset   : in  std_logic;
    ipb_in  : in  ipb_wbus;
    ipb_out : out ipb_rbus;
    to_hw   : out t_prototype_to_hw;
    from_hw : in  t_prototype_from_hw
  );
end entity prototype_ipb_endpoint;

architecture rtl of prototype_ipb_endpoint is

  signal m2s : t_lb_m2s;
  signal s2m : t_lb_s2m;

begin

  i_regfile : entity work.prototype_regfile
    generic map (
      G_BASE_ADDRESS       => G_BASE_ADDRESS,
      G_CHECK_BASE_ADDRESS => G_CHECK_BASE_ADDRESS,
      G_MODULE_ADDR_WIDTH  => G_MODULE_ADDR_WIDTH,
      G_RESET_ACTIVE_LOW   => false)      -- IPBus reset is sync active-high
    port map (
      clk     => clk,
      reset   => reset,
      lb_m2s  => m2s,
      lb_s2m  => s2m,
      to_hw   => to_hw,
      from_hw => from_hw);

  m2s.address <= ipb_in.ipb_addr(31 downto 0);
  m2s.wdata   <= ipb_in.ipb_wdata;
  m2s.wen     <= ipb_in.ipb_strobe and ipb_in.ipb_write;
  m2s.ren     <= ipb_in.ipb_strobe and not ipb_in.ipb_write;

  ipb_out.ipb_rdata <= s2m.rdata;
  ipb_out.ipb_ack   <= s2m.ack;
  ipb_out.ipb_err   <= s2m.err;

end architecture rtl;
